add_filter( 'woocommerce_bacs_accounts', 'perfectpixel_bank_accounts_by_currency', 10, 2 );

function perfectpixel_bank_accounts_by_currency( $accounts, $order_id = 0 ) {
	// Currency => IBAN or account number of the bank account to show.
	$by_currency = array(
		'EUR' => 'GR0000000000000000000000000',
		'USD' => 'GB00XXXX00000000000000',
	);

	$order = $order_id ? wc_get_order( $order_id ) : false;
	if ( ! $order || empty( $by_currency[ $order->get_currency() ] ) ) {
		return $accounts;
	}
	$wanted = strtoupper( str_replace( ' ', '', $by_currency[ $order->get_currency() ] ) );

	$filtered = array_filter(
		(array) $accounts,
		static function ( $account ) use ( $wanted ) {
			$iban   = strtoupper( str_replace( ' ', '', (string) ( $account['iban'] ?? '' ) ) );
			$number = strtoupper( str_replace( ' ', '', (string) ( $account['account_number'] ?? '' ) ) );
			return $wanted === $iban || $wanted === $number;
		}
	);
	return $filtered ? array_values( $filtered ) : $accounts;
}
